import type { Request, Response } from 'express';
import { sendEmail } from '../../email.js';

interface ContactBody {
  name?: string;
  email?: string;
  phone?: string;
  service?: string;
  message?: string;
}

export default async function handler(req: Request, res: Response) {
  const { name, email, phone, service, message } = req.body as ContactBody;

  if (!name || !email || !message) {
    return res.status(400).json({ error: 'Name, email, and message are required.' });
  }

  const recipient =
    process.env.CONTACT_FORM_RECIPIENT_EMAIL || 'owner@sparkle-clean.com';

  const serviceLabel = service ? `\nService Requested: ${service}` : '';
  const phoneLabel = phone ? `\nPhone: ${phone}` : '';

  try {
    await sendEmail({
      to: recipient,
      replyTo: email,
      subject: `New Quote Request from ${name} — Sparkle Clean`,
      text: `You have a new quote request from your website.\n\nName: ${name}\nEmail: ${email}${phoneLabel}${serviceLabel}\n\nMessage:\n${message}`,
      html: `
        <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto;">
          <h2 style="color: #4A9FC4;">New Quote Request — Sparkle Clean</h2>
          <table style="width:100%; border-collapse: collapse;">
            <tr><td style="padding: 8px 0; font-weight: bold; width: 140px;">Name</td><td>${name}</td></tr>
            <tr><td style="padding: 8px 0; font-weight: bold;">Email</td><td><a href="mailto:${email}">${email}</a></td></tr>
            ${phone ? `<tr><td style="padding: 8px 0; font-weight: bold;">Phone</td><td>${phone}</td></tr>` : ''}
            ${service ? `<tr><td style="padding: 8px 0; font-weight: bold;">Service</td><td>${service}</td></tr>` : ''}
          </table>
          <h3 style="margin-top: 24px; color: #4A9FC4;">Message</h3>
          <p style="background: #f5f5f5; padding: 16px; border-radius: 8px; white-space: pre-wrap;">${message}</p>
        </div>
      `,
    });

    return res.status(200).json({ ok: true });
  } catch (err) {
    console.error('contact.form.send-failed', err);
    return res.status(500).json({ error: 'Failed to send message. Please try again.' });
  }
}

