import { Helmet } from '@dr.pogodin/react-helmet';
import { useState } from 'react';
import { motion } from 'motion/react';
import { Phone, MapPin, Clock, CheckCircle2, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.35, ease: 'easeOut' as const, delay },
  }),
};

const services = [
  'Standard Clean',
  'Deep Clean',
  'Move-In / Move-Out',
  'Recurring Service',
  'Not sure yet',
];

export default function ContactPage() {
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    service: '',
    message: '',
  });
  const [status, setStatus] = useState<'idle' | 'sending' | 'success' | 'error'>('idle');
  const [errorMsg, setErrorMsg] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('sending');
    setErrorMsg('');

    try {
      const res = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Something went wrong.');
      setStatus('success');
    } catch (err) {
      setStatus('error');
      setErrorMsg(err instanceof Error ? err.message : 'Something went wrong. Please try again.');
    }
  };

  return (
    <>
      <Helmet>
        <title>Contact — Sparkle Clean</title>
        <meta
          name="description"
          content="Get a free quote from Sparkle Clean. Call us or fill out our quick form and we'll get back to you within 24 hours."
        />
      </Helmet>

      {/* Page header */}
      <section className="bg-muted border-b border-border py-16 md:py-20">
        <div className="container mx-auto px-4">
          <motion.div
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            className="max-w-xl"
          >
            <p className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
              Get in Touch
            </p>
            <h1 className="text-4xl md:text-5xl font-bold text-foreground leading-tight mb-4">
              Get your free quote
            </h1>
            <p className="text-muted-foreground text-lg leading-relaxed">
              No contracts, no surprises. Fill out the form and we'll get back to you within 24 hours — usually much sooner.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Main content */}
      <section className="py-16 md:py-24 bg-background">
        <div className="container mx-auto px-4">
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-12 lg:gap-16">

            {/* Contact info sidebar */}
            <motion.div
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.1}
              className="lg:col-span-2 flex flex-col gap-8"
            >
              <div>
                <h2 className="text-xl font-bold text-foreground mb-5">Contact info</h2>
                <ul className="flex flex-col gap-5">
                  <li className="flex items-start gap-3.5">
                    <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center shrink-0 mt-0.5">
                      <Phone size={17} className="text-primary" />
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground uppercase tracking-wider mb-0.5">Phone</p>
                      <a href="tel:5558675309" className="font-semibold text-foreground hover:text-primary transition-colors">
                        (555) 867-5309
                      </a>
                    </div>
                  </li>
                  <li className="flex items-start gap-3.5">
                    <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center shrink-0 mt-0.5">
                      <MapPin size={17} className="text-primary" />
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground uppercase tracking-wider mb-0.5">Service Area</p>
                      <p className="font-semibold text-foreground">Greater metro area &amp; surrounding communities</p>
                    </div>
                  </li>
                  <li className="flex items-start gap-3.5">
                    <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center shrink-0 mt-0.5">
                      <Clock size={17} className="text-primary" />
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground uppercase tracking-wider mb-0.5">Hours</p>
                      <p className="font-semibold text-foreground">Mon – Fri: 8am – 6pm</p>
                      <p className="text-sm text-muted-foreground">Sat: 9am – 4pm</p>
                    </div>
                  </li>
                </ul>
              </div>

              {/* Trust points */}
              <div className="bg-muted rounded-2xl p-6 border border-border">
                <h3 className="font-bold text-foreground mb-4">Why choose Sparkle Clean?</h3>
                <ul className="flex flex-col gap-3">
                  {[
                    'Free, no-obligation estimates',
                    'Insured & bonded for your peace of mind',
                    '100% satisfaction guarantee',
                    'Flexible scheduling around your life',
                    'Eco-friendly cleaning products available',
                  ].map((item) => (
                    <li key={item} className="flex items-start gap-2.5 text-sm text-foreground/80">
                      <CheckCircle2 size={15} className="text-primary shrink-0 mt-0.5" />
                      {item}
                    </li>
                  ))}
                </ul>
              </div>
            </motion.div>

            {/* Form */}
            <motion.div
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.2}
              className="lg:col-span-3"
            >
              {status === 'success' ? (
                <div className="flex flex-col items-center justify-center text-center py-16 px-8 bg-muted rounded-2xl border border-border h-full">
                  <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mb-5">
                    <CheckCircle2 size={32} className="text-primary" />
                  </div>
                  <h2 className="text-2xl font-bold text-foreground mb-3">Message sent!</h2>
                  <p className="text-muted-foreground max-w-sm leading-relaxed">
                    Thanks for reaching out. We'll get back to you within 24 hours with your free quote.
                  </p>
                  <button
                    onClick={() => { setStatus('idle'); setForm({ name: '', email: '', phone: '', service: '', message: '' }); }}
                    className="mt-8 inline-flex items-center gap-2 text-primary font-semibold text-sm hover:gap-3 transition-all duration-200"
                  >
                    Send another message <ArrowRight size={15} />
                  </button>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="bg-card rounded-2xl border border-border p-8 md:p-10 shadow-sm flex flex-col gap-6">
                  <h2 className="text-xl font-bold text-foreground">Request a free quote</h2>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div className="flex flex-col gap-1.5">
                      <Label htmlFor="name">Full name <span className="text-destructive">*</span></Label>
                      <Input
                        id="name"
                        name="name"
                        placeholder="Jane Smith"
                        value={form.name}
                        onChange={handleChange}
                        required
                        disabled={status === 'sending'}
                      />
                    </div>
                    <div className="flex flex-col gap-1.5">
                      <Label htmlFor="email">Email address <span className="text-destructive">*</span></Label>
                      <Input
                        id="email"
                        name="email"
                        type="email"
                        placeholder="jane@example.com"
                        value={form.email}
                        onChange={handleChange}
                        required
                        disabled={status === 'sending'}
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div className="flex flex-col gap-1.5">
                      <Label htmlFor="phone">Phone number</Label>
                      <Input
                        id="phone"
                        name="phone"
                        type="tel"
                        placeholder="(555) 000-0000"
                        value={form.phone}
                        onChange={handleChange}
                        disabled={status === 'sending'}
                      />
                    </div>
                    <div className="flex flex-col gap-1.5">
                      <Label htmlFor="service">Service needed</Label>
                      <Select
                        value={form.service}
                        onValueChange={(val) => setForm((prev) => ({ ...prev, service: val }))}
                        disabled={status === 'sending'}
                      >
                        <SelectTrigger id="service">
                          <SelectValue placeholder="Select a service…" />
                        </SelectTrigger>
                        <SelectContent>
                          {services.map((s) => (
                            <SelectItem key={s} value={s}>{s}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>

                  <div className="flex flex-col gap-1.5">
                    <Label htmlFor="message">Message <span className="text-destructive">*</span></Label>
                    <Textarea
                      id="message"
                      name="message"
                      placeholder="Tell us about your home — number of bedrooms, bathrooms, any special requests…"
                      rows={5}
                      value={form.message}
                      onChange={handleChange}
                      required
                      disabled={status === 'sending'}
                      className="resize-none"
                    />
                  </div>

                  {status === 'error' && (
                    <p className="text-sm text-destructive bg-destructive/10 rounded-lg px-4 py-3">{errorMsg}</p>
                  )}

                  <Button
                    type="submit"
                    disabled={status === 'sending'}
                    className="w-full sm:w-auto bg-accent text-foreground font-bold hover:brightness-105 rounded-full px-8 py-3 text-base transition-all duration-200"
                  >
                    {status === 'sending' ? 'Sending…' : 'Send my request'}
                  </Button>

                  <p className="text-xs text-muted-foreground">
                    We'll respond within 24 hours. No spam, ever.
                  </p>
                </form>
              )}
            </motion.div>
          </div>
        </div>
      </section>
    </>
  );
}

